"""Blocks of the display (docs: the display is a 320x240, 16-bit (RGB565) framebuffer RAM in the peripheral window, scanned out as 640x480 VGA with every pixel doubled).
Map: peripheral window 0x1001_0000 to 0x100F_FFFF; the framebuffer is the 256 KB at 0x1004_0000 (the pixels at its start, row after row, two 16-bit pixels per word, the
left one in the low half), the display registers are at 0x1001_0500, the two PS/2 ports at 0x1001_0300 and 0x1001_0400. Generated by BARG against hand-written golden
models (golden/<name>.py), never shown to the generator."""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent.parent / "gpu-soc"))
from build_gpu_soc import block, i, o, port  # noqa: E402

W = 32
CLK = port("p_clk", "clk", "in", 1, "clock")
RST = port("p_rst", "rst", "in", 1, "reset")

VGA_TIMING = block("b_vga_timing", "vga_timing", """
    The timing of a 640x480 VGA picture, pixel clock one fourth of the clock. Held state, all 0 at reset: div (2 bits), hc (10 bits, the pixel column counter) and vc (10
    bits, the line counter). On each rising clock edge, after reset: div becomes div plus 1 (wrapping from 3 to 0); and when div is 3 before the edge: hc becomes hc plus 1,
    except when hc is 799, then hc becomes 0 and vc becomes vc plus 1 (vc becomes 0 when it is 524). Outputs, combinational from the held state and enable (1 bit, an input):
    active is 1 when hc is less than 640 and vc is less than 480. de is active AND enable. hs is 0 when hc is from 656 to 751 (inclusive) and 1 otherwise. vs is 0 when vc is
    490 or 491 and 1 otherwise. vbl is 1 when vc is 480 or more. frame is 1 when div is 3, hc is 799 and vc is 524 (the last cycle of a picture). widx (16 bits) is (vc shifted
    right by 1) times 160 plus (hc shifted right by 2), truncated to 16 bits. half is bit 1 of hc.
""", [CLK, RST, i("enable", 1, "control"), o("de", 1, "control"), o("hs", 1, "control"), o("vs", 1, "control"), o("vbl", 1, "control"),
      o("frame", 1, "control"), o("widx", 16, "addr"), o("half", 1, "control")], reset="sync", latency=1)

PX_PICK = block("b_px_pick", "px_pick", """
    Combinational. The colour of the pixel on the display wires. word (32 bits) holds two 16-bit pixels, the left one in bits 15:0 and the right one in bits 31:16; half (1 bit)
    says which one is shown: the one in bits 31:16 when half is 1, the one in bits 15:0 when half is 0. A pixel is in the format RGB565: bits 15:11 are red, bits 10:5 green and
    bits 4:0 blue. r (5 bits), g (6 bits) and b (5 bits) are the red, green and blue of the chosen pixel when de (1 bit) is 1, and all 0 when de is 0. No clock, no reset, no state.
""", [i("word", W, "data"), i("half", 1, "control"), i("de", 1, "control"), o("r", 5, "data"), o("g", 6, "data"), o("b", 5, "data")])

DISP_REGS = block("b_disp_regs", "disp_regs", """
    The registers of the display. Held state, all 0 at reset: en (1 bit) and frames (32 bits). On each rising clock edge, after reset: when we is 1 and bits 3:2 of addr are 0,
    en becomes bit 0 of wdata; and when frame (1 bit, an input) is 1, frames becomes frames plus 1 (wrapping at 32 bits). rdata (32 bits, combinational on addr and the held state
    and vbl (1 bit, an input), whether or not we is 1) by bits 3:2 of addr: 0 is vbl in bit 8 and en in bit 0 (every other bit 0); 1 is 0x00F00140 (the picture size: height 240 in
    bits 31:16 and width 320 in bits 15:0); 2 is frames; 3 is 0. enable is en.
""", [CLK, RST, i("we", 1, "control"), i("addr", W, "addr"), i("wdata", W, "data"), i("frame", 1, "control"), i("vbl", 1, "control"), o("rdata", W, "data"),
      o("enable", 1, "control")], reset="sync", latency=1)

PDEV_BUS2 = block("b_pdev_bus2", "pdev_bus2", """
    Combinational. The device decode and read multiplexer of the peripheral window (the 960 KB from 0x10010000). pa (32 bits) is the access address and pw (1 bit) says a write is
    happening. The framebuffer is chosen when bits 19:18 of pa are 01 (binary); otherwise the device is chosen by bits 11:8 of pa: 0 is the GPIO, 1 the SPI master, 2 the I2C master,
    3 the keyboard port, 4 the mouse port, 5 the display registers, anything else no device. gpio_we, spi_we, i2c_we, kbd_we, mouse_we, disp_we and fb_we are 1 when pw is 1 and
    the device (or the framebuffer) is the one they are named for, and 0 otherwise. prdata (32 bits) is the rdata input of the chosen device (gpio_rdata, spi_rdata, i2c_rdata,
    kbd_rdata, mouse_rdata, disp_rdata or fb_rdata), and 0 when none is chosen. No clock, no reset, no state.
""", [i("pa", W, "data"), i("pw", 1, "control"), i("gpio_rdata", W, "data"), i("spi_rdata", W, "data"), i("i2c_rdata", W, "data"), i("kbd_rdata", W, "data"),
      i("mouse_rdata", W, "data"), i("disp_rdata", W, "data"), i("fb_rdata", W, "data"), o("gpio_we", 1, "control"), o("spi_we", 1, "control"), o("i2c_we", 1, "control"),
      o("kbd_we", 1, "control"), o("mouse_we", 1, "control"), o("disp_we", 1, "control"), o("fb_we", 1, "control"), o("prdata", W, "data")])

PDEV_BUS3 = block("b_pdev_bus3", "pdev_bus3", """
    Combinational. The device decode and read multiplexer of the peripheral window (the 64 KB from 0x10010000), with the two PS/2 ports. pa (32 bits) is the access address, pw (1 bit) says a
    write is happening and pr (1 bit) says a read with side effects is happening. The device is chosen by bits 11:8 of pa: 0 is the GPIO, 1 the SPI master, 2 the I2C master, 3 the keyboard
    port, 4 the mouse port, anything else no device. gpio_we, spi_we, i2c_we, kbd_we and mouse_we are 1 when pw is 1 and the device is the one they are named for, and 0 otherwise. kbd_re and
    mouse_re are 1 when pr is 1 and the device is the keyboard port or the mouse port respectively, and 0 otherwise. prdata (32 bits) is the rdata input of the chosen device (gpio_rdata,
    spi_rdata, i2c_rdata, kbd_rdata or mouse_rdata), and 0 when no device is chosen. No clock, no reset, no state.
""", [i("pa", W, "data"), i("pw", 1, "control"), i("pr", 1, "control"), i("gpio_rdata", W, "data"), i("spi_rdata", W, "data"), i("i2c_rdata", W, "data"), i("kbd_rdata", W, "data"),
      i("mouse_rdata", W, "data"), o("gpio_we", 1, "control"), o("spi_we", 1, "control"), o("i2c_we", 1, "control"), o("kbd_we", 1, "control"), o("mouse_we", 1, "control"),
      o("kbd_re", 1, "control"), o("mouse_re", 1, "control"), o("prdata", W, "data")])

BLOCKS = [VGA_TIMING, PX_PICK, DISP_REGS, PDEV_BUS2, PDEV_BUS3]
